import { useRef, useEffect } from 'preact/hooks';
import { FunctionalComponent } from 'preact';

import { getFaviconUrl } from '../../slice/selectors/suggestions/utils';
import { WebPageResponse } from '../../slice/types';

import styles from './styles.module.scss';
import excluded from './excluded.json';

const cleanHTML = (str) =>
  str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const formatSnippet = (q, snippet) => {
  try {
    const excludedRegex = new RegExp(
      `(${excluded.map((w) => `\\b${w}\\b`).join('|')})`,
      'ig'
    );
    const query = q
      .replace(/[^\w\s]/gi, '')
      .replace(excludedRegex, '')
      .trim()
      .split(' ')
      .map((word) => word.trim())
      .filter(Boolean);
    const regex = new RegExp(
      `(\\b[a-z]+\\d+|\\d+(\\s[a-z]+)?(?!;)\\b|${query
        .map((w) => `\\b${w}\\b`)
        .join('|')})`,
      'ig'
    );

    return cleanHTML(snippet).replace(regex, '<b>$1</b>');
  } catch (err) {
    return cleanHTML(snippet);
  }
};

interface Props {
  q: string;
  data: WebPageResponse,
  $form: HTMLFormElement,
  $suggestion: HTMLElement,
}

const InstantAnswer: FunctionalComponent<Props> = ({ q, data, $suggestion, $form }: Props) => {
  const $el = useRef<HTMLDivElement>(null);
  const $arrow = useRef<HTMLDivElement>(null);

  const getWidth = () =>
    Math.min((window.innerWidth - $form.offsetWidth) / 2, 500);

  useEffect(() => {
    if (!$el.current) return;

    const width = getWidth();
    $el.current.style.width = `${width}px`;
    $el.current.style.left = `-${width}px`;
    $el.current.style.top = '0px';
    $el.current.style.opacity = '0';

    if (!$arrow.current || !$suggestion) return;

    const suggestionRect = $suggestion.getBoundingClientRect();

    const containerRect = $el.current.getBoundingClientRect();
    const top = Math.max(
      suggestionRect.y - containerRect.y - containerRect.height + 60,
      -containerRect.y + 20,
    );
    $el.current.style.top = `${top}px`;

    $arrow.current.style.top = '0px';
    const arrowTop = suggestionRect.y - $arrow.current.getBoundingClientRect().y;
    $arrow.current.style.top = `${arrowTop + 9}px`;
    $el.current.style.opacity = '1';
  }, [data, $suggestion]);

  if (getWidth() < 250) return null;

  return (
    <div
      ref={$el}
      className={styles.container}
    >
      <div className={styles.innerContainer}>
        <div ref={$arrow} className={styles.arrow} />

        {data.thumbnailUrl && (
          <img className={styles.thumbnail} src={data.thumbnailUrl} alt='' />
        )}

        <p
          className={styles.description}
          dangerouslySetInnerHTML={{ __html: formatSnippet(q, data.snippet) }}
        />

        <a className={styles.link} href={data.url}>
          <div className={styles.title} dangerouslySetInnerHTML={{
            __html: formatSnippet(q, data.name),
          }} />
          <div className={styles.label}>
            <img
              className={styles.favicon}
              src={getFaviconUrl(data.url)}
              alt="favicon"
              height={14}
              width={14}
            />
            {data.displayUrl}
          </div>
        </a>
      </div>
    </div>
  )
};

export default InstantAnswer;
